// Waffle Chart — Basic, route: jsx
// Source: original:gaps/waffle
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from waffle ----
// Global electricity generation mix, percent. Hardcoded plausible values that sum
// to exactly 100 so the waffle's one-cell-per-percent grain is honest.
const electricityMix: { name: string; value: number }[] = [
  { name: 'Coal', value: 35 },
  { name: 'Natural gas', value: 22 },
  { name: 'Hydro', value: 15 },
  { name: 'Nuclear', value: 9 },
  { name: 'Wind', value: 8 },
  { name: 'Solar', value: 6 },
  { name: 'Other', value: 5 }
];

const GRID = 10;
const GAP = 2;
const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };
const LEGEND_ROW = 18;

/** Parts of a whole; each of the 100 cells is one percent. */
export type Data = { name: string; value: number }[];

// Largest-remainder allocation: cells always sum to exactly GRID*GRID, so rounding
// error is distributed across categories rather than accumulated into the last one.
function allocate(data: Data, cells: number) {
  const total = d3.sum(data, (d) => d.value) || 1;
  const exact = data.map((d) => (d.value / total) * cells);
  const floors = exact.map(Math.floor);
  let remaining = cells - d3.sum(floors);
  const order = exact
    .map((v, i) => ({ i, frac: v - Math.floor(v) }))
    .sort((a, b) => b.frac - a.frac);
  const counts = [...floors];
  for (const { i } of order) {
    if (remaining <= 0) break;
    counts[i] += 1;
    remaining -= 1;
  }
  return counts;
}

export default function WaffleChart({ data = electricityMix, width }: { data?: Data; width: number }) {
  const counts = useMemo(() => allocate(data, GRID * GRID), [data]);

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.map((d) => d.name))
        .range(d3.schemeObservable10),
    [data]
  );

  const gridSize = width - MARGIN.left - MARGIN.right;
  const cell = (gridSize - GAP * (GRID - 1)) / GRID;
  const legendHeight = data.length * LEGEND_ROW;
  const height = MARGIN.top + gridSize + 12 + legendHeight + MARGIN.bottom;

  const cells = useMemo(() => {
    const out: { name: string; index: number }[] = [];
    data.forEach((d, i) => {
      for (let k = 0; k < counts[i]; k++) out.push({ name: d.name, index: out.length });
    });
    return out;
  }, [data, counts]);

  if (width === 0) return null;

  const total = d3.sum(data, (d) => d.value) || 1;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Waffle chart of the global electricity generation mix, one cell per percent"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {cells.map(({ name, index }) => {
          // Fill bottom-up, row by row, so shares read like a rising level.
          const row = GRID - 1 - Math.floor(index / GRID);
          const col = index % GRID;
          return (
            <rect
              key={index}
              x={col * (cell + GAP)}
              y={row * (cell + GAP)}
              width={cell}
              height={cell}
              rx={1.5}
              fill={color(name)}
            />
          );
        })}
        <g transform={`translate(0,${gridSize + 12})`}>
          {data.map((d, i) => (
            <g key={d.name} transform={`translate(0,${i * LEGEND_ROW})`}>
              <rect width={11} height={11} rx={1.5} fill={color(d.name)} />
              <text x={16} y={9} fontSize={11} fill="var(--text)">
                {d.name} — {d3.format('.0%')(d.value / total)}
              </text>
            </g>
          ))}
        </g>
      </g>
    </svg>
  );
}
